INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66534304', 66534304, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'INSPEKTORAT UTAMA BADAN POM', 'Transport pada Audit Balai Besar/Balai POM', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 49770000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '( 12, OK, @ 4147500 )', '1. Transpor ( 12, OK, @ 4147500 );', 'Penyediaan jasa transportasi bagi tim guna mendukung mobilisasi dalam rangka audit dari tempat kedudukan menuju lokasi objek pemantauan. Spesifikasi ini mencakup penggunaan moda transportasi darat yang memadai—seperti kendaraan sewa, taksi, atau sarana transportasi umum lainnya—yang dipilih dengan mempertimbangkan prinsip efektivitas waktu, efisiensi anggaran, serta kemudahan akses menuju lokasi data atau pihak terkait. Ruang lingkup pekerjaan juga meliputi biaya transportasi lokal serta biaya transportasi dari kediaman/kantor menuju titik keberangkatan (stasiun/bandara/terminal) sesuai dengan rute yang tercantum dalam Surat Tugas. Seluruh komponen biaya wajib mengacu pada ketentuan tarif yang berlaku atau batas tertinggi Standar Biaya Masukan (SBM) tahun anggaran berjalan, dengan mekanisme pertanggungjawaban berdasarkan biaya riil (at cost) yang didukung oleh bukti pembayaran yang sah sesuai kaidah akuntabilitas keuangan negara.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2800333);
