INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66534302', 66534302, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'INSPEKTORAT UTAMA BADAN POM', 'Penginapan Pimpinan pada Bimbingan Teknis dan Perjalanan Dinas Pimpinan Inspektorat I', 'Jasa Lainnya', 'Dikecualikan', 'DKI Jakarta, Jakarta Pusat (Kota)', 10080000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '( 6, OH, @ 1680000 )', '1. Penginapan ( 6, OH, @ 1680000 );', 'Penyediaan jasa akomodasi penginapan bagi Pejabat Eselon II guna mendukung pelaksanaan tugas kedinasan dan representasi instansi di lokasi tujuan. Spesifikasi pekerjaan mencakup penyediaan kamar sesuai ketersediaan dan standar kelas jabatan yang memiliki fasilitas penunjang kerja dan privasi yang memadai. Hotel dipilih dengan mempertimbangkan faktor keamanan, kenyamanan, serta kedekatan akses menuju lokasi kegiatan guna efisiensi mobilisasi pimpinan. Ruang lingkup layanan sudah termasuk fasilitas sarapan pagi serta akses penunjang komunikasi (Wi-Fi) di dalam kamar. Penentuan tarif hotel wajib merujuk pada batas tertinggi Standar Biaya Masukan (SBM) tahun anggaran berjalan yang berlaku khusus untuk Pejabat Eselon II di wilayah lokasi penugasan. Mekanisme pertanggungjawaban dilaksanakan berdasarkan biaya riil (at cost) yang dibuktikan dengan kuitansi atau faktur resmi hotel serta dokumen pendukung lainnya sesuai dengan ketentuan tata kelola keuangan negara yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2802064);
