INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66534715', 66534715, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'INSPEKTORAT UTAMA BADAN POM', 'Penginapan pada Audit Tujuan Tertentu', 'Jasa Lainnya', 'Dikecualikan', 'Sumatera Barat, Payakumbuh (Kota)', 9000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 12, OH, @ 750000 )', '1. Penginapan ( 12, OH, @ 750000 );', 'Penyediaan jasa akomodasi penginapan bagi tim auditor guna mendukung efektivitas dan kelancaran pelaksanaan tugas audit di lokasi tujuan. Lingkup pekerjaan mencakup penyediaan kamar dengan standar fasilitas yang memadai untuk istirahat dan koordinasi tim, dengan kapasitas hunian yang disesuaikan dengan ketentuan kelas jabatan atau golongan masing-masing personil sesuai peraturan perjalanan dinas yang berlaku. Lokasi penginapan dipilih berdasarkan prinsip kedekatan akses dengan objek pemeriksaan (auditee) untuk optimalisasi waktu pengawasan dan efisiensi transportasi lokal. Besaran biaya penginapan wajib mematuhi batas tertinggi plafon Standar Biaya Masukan (SBM) tahun anggaran berjalan untuk wilayah terkait, dengan mekanisme pembayaran berdasarkan biaya riil (at cost) yang dibuktikan melalui kuitansi atau faktur resmi serta dokumen pendukung lainnya sesuai ketentuan pertanggungjawaban keuangan negara.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2802609);
