INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66535478', 66535478, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'INSPEKTORAT UTAMA BADAN POM', 'Penginapan pada Sosialisasi Program Anti Korupsi', 'Jasa Lainnya', 'Dikecualikan', 'DKI Jakarta, Jakarta Pusat (Kota)', 20400000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '( 20, OH, @ 1020000 )', '1. Penginapan ( 20, OH, @ 1020000 );', 'Penyediaan jasa akomodasi penginapan bagi tim sosialisasi guna mendukung kelancaran pelaksanaan program edukasi dan Sosialisasi Anti Korupsi di lingkungan Unit Pelaksana Teknis (UPT). Spesifikasi pekerjaan mencakup penyediaan kamar dengan fasilitas yang memadai untuk istirahat serta koordinasi tim, dengan kapasitas hunian yang disesuaikan berdasarkan ketentuan kelas jabatan dan golongan masing-masing personil (seperti PNS Golongan II/III) sesuai aturan perjalanan dinas yang berlaku. Mengingat target kegiatan mencakup jangkauan edukasi yang luas hingga ke lokasi UPT, pemilihan penginapan diprioritaskan pada area yang memiliki aksesibilitas optimal serta kedekatan dengan titik pelaksanaan sosialisasi guna menjamin ketepatan jadwal dan efektivitas koordinasi dengan jajaran pegawai di UPT setempat. Besaran biaya penginapan wajib mematuhi batasan tertinggi Standar Biaya Masukan (SBM) tahun anggaran berjalan untuk wilayah terkait, dengan mekanisme pertanggungjawaban berdasarkan biaya riil (at cost) yang dibuktikan melalui kuitansi atau faktur resmi hotel sebagai dokumen validasi keuangan negara yang sah.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2802722);
