INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66534296', 66534296, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'INSPEKTORAT UTAMA BADAN POM', 'Transport Pendamping pada Bimbingan Teknis dan Perjalanan Dinas Pimpinan Inspektorat I', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 10713000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '( 3, OK, @ 3571000 )', '1. Transport ( 3, OK, @ 3571000 );', 'Penyediaan jasa transportasi guna mendukung pelaksanaan perjalanan dinas biasa pendamping dalam rangka Bimbingan Teknis dan Perjalanan Dinas Pimpinan. Lingkup pekerjaan mencakup penyediaan moda transportasi darat, laut, atau udara dari tempat kedudukan menuju lokasi tujuan (pergi-pulang), serta transportasi lokal yang diperlukan selama masa penugasan. Dalam hal ini termasuk biaya transportasi dari tempat kedudukan ke lokasi moda transportasi. Seluruh pemilihan rute, moda transportasi, dan tempat menginap dilakukan dengan mengutamakan prinsip efektivitas waktu, efisiensi anggaran, serta pencapaian target kinerja penugasan. Besaran biaya yang dikeluarkan wajib mematuhi batasan tertinggi Standar Biaya Masukan (SBM) tahun anggaran berjalan, dengan mekanisme pertanggungjawaban berdasarkan biaya riil (at cost) yang didukung oleh bukti pembayaran atau dokumen elektronik yang sah sesuai ketentuan peraturan perundang-undangan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2802987);
