INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66535463', 66535463, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'INSPEKTORAT UTAMA BADAN POM', 'Snack rapat pada Evaluasi dan Koordinasi Pelaksanaan Kegiatan', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 4536000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 189, OK, @ 24000 )', '1. Snack rapat biasa DKI Jakarta ( 189, OK, @ 24000 );', 'Penyediaan kudapan (snack) guna mendukung kelancaran pelaksanaan Evaluasi dan Koordinasi Pelaksanaan Kegiatan agar produktivitas tim tetap terjaga selama sesi diskusi teknis berlangsung. Spesifikasi hidangan mencakup penyajian variasi penganan yang layak santap. Penyajian kudapan dilakukan dengan mempertimbangkan efektivitas waktu serta fleksibilitas ruang koordinasi guna menjamin kelancaran alur pemaparan progres kegiatan dan evaluasi hambatan di lapangan. Penentuan harga satuan paket kudapan wajib sepenuhnya patuh pada batas tertinggi Standar Biaya Masukan (SBM) tahun anggaran berjalan yang berlaku untuk kategori snack rapat di wilayah terkait, dengan syarat pelaksanaan rapat koordinasi sekurang-kurangnya 2 (dua) jam. Seluruh pengadaan ini mengutamakan prinsip efisiensi anggaran negara, di mana pembayaran dilakukan berdasarkan jumlah kehadiran riil peserta yang tervalidasi melalui dokumen absensi dan bukti bayar yang sah.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2803006);
