INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66535473', 66535473, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'INSPEKTORAT UTAMA BADAN POM', 'Snack Rapat pada Pemantauan Progres Penyelesaian TL Temuan Pemeriksaan', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 2592000, 'June 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 108, OK, @ 24000 )', '1. Snack Rapat Biasa D.K.I. JAKARTA ( 108, OK, @ 24000 );', 'Penyediaan kudapan guna mendukung kelancaran kegiatan Pemantauan Progres Penyelesaian Tindak Lanjut (TL) Temuan Pemeriksaan di lokasi kegiatan. Spesifikasi hidangan mencakup penyajian menu yang layak santap. Mengingat sifat kegiatan yang memerlukan koordinasi intensif serta diskusi teknis dalam proses verifikasi dokumen bukti dukung (evidence) tindak lanjut, penyajian kudapan dapat dilakukan secara prasmanan (buffet) atau kotak (box) dengan mempertimbangkan efektivitas waktu serta ketersediaan ruang rapat di lokasi pemeriksaan. Penyediaan kudapan hanya dapat dilakukan dalam hal rapat dilakukan sesuai kaidah pada standar biaya dengan batas tertinggi harga sebagaimana dicantumkan pada standar biaya.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2803205);
