INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66535464', 66535464, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'INSPEKTORAT UTAMA BADAN POM', 'Pencetakan untuk Sosialisasi Program Anti Korupsi', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 12600000, 'June 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1, PKT, @ 12600000 )', '1. Pencetakan ( 1, PKT, @ 12600000 );', 'Penyediaan jasa cetak bahan publikasi dan edukasi guna mendukung pelaksanaan program Sosialisasi Anti Korupsi, baik di lingkungan Kantor Pusat maupun Unit Pelaksana Teknis (UPT). Spesifikasi pekerjaan mencakup penggandaan materi sosialisasi yang dapat berupa modul, leaflet, poster, buku saku, atau bahan cetak edukatif lainnya yang memuat pesan-pesan integritas dan antikorupsi. Bahan cetak wajib menggunakan material yang berkualitas, rapi, dan memiliki tingkat keterbacaan yang baik guna menjamin efektivitas penyampaian pesan kepada seluruh pegawai dan pemangku kepentingan di seluruh lini organisasi. Jumlah dan jenis cetakan disesuaikan dengan kebutuhan teknis pelaksanaan kegiatan serta target sebaran edukasi yang telah ditetapkan dalam rencana kerja. Penentuan harga satuan bahan cetak wajib mengacu pada standar harga pasar yang wajar dengan tetap memperhatikan aspek efisiensi. Mekanisme pembayaran dilakukan berdasarkan realisasi volume cetak nyata yang telah diterima dengan baik, didukung oleh kuitansi serta pemenuhan kewajiban administrasi perpajakan yang sah.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2804037);
