INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66535479', 66535479, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'INSPEKTORAT UTAMA BADAN POM', 'Transport pada Pemantauan SPIP', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 10840000, 'June 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '( 3, OK, @ 3613334 )', '1. Transport ( 3, OK, @ 3613334 );', 'Penyediaan jasa transportasi bagi tim pendamping guna mendukung kelancaran kegiatan pemantauan dan evaluasi Penyelenggaraan SPIP Terintegrasi, khususnya dalam rangka mendampingi tim BPKP saat melakukan verifikasi lapangan di daerah. Spesifikasi ini mencakup penggunaan moda transportasi darat yang memadai yang dipilih berdasarkan prinsip efektivitas waktu, keamanan, serta kemudahan akses menuju lokasi satuan kerja atau titik sampling yang ditentukan. Ruang lingkup pekerjaan meliputi biaya transportasi dari tempat kedudukan menuju lokasi tujuan (pergi-pulang), transportasi lokal antar titik pemeriksaan di daerah, serta biaya transportasi pendukung dari kediaman/kantor menuju titik keberangkatan (bandara/stasiun) sesuai rute penugasan. Mengingat sifat kegiatan yang memerlukan mobilitas tinggi untuk menjangkau berbagai lokasi sampling dalam waktu terbatas, pemilihan jenis kendaraan harus mempertimbangkan kondisi geografis dan kelancaran koordinasi tim di lapangan. Besaran biaya wajib mematuhi batasan tertinggi Standar Biaya Masukan (SBM) tahun anggaran berjalan, dengan mekanisme pertanggungjawaban berdasarkan biaya riil (at cost) yang dibuktikan melalui kuitansi atau dokumen pembayaran sah lainnya sesuai ketentuan tata kelola keuangan negara.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2804508);
