INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66535480', 66535480, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'INSPEKTORAT UTAMA BADAN POM', 'Penginapan pada Pemantauan SPIP', 'Jasa Lainnya', 'Dikecualikan', 'DKI Jakarta, Jakarta Pusat (Kota)', 5322000, 'June 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '( 6, OH, @ 887000 )', '1. Penginapan ( 6, OH, @ 887000 );', 'Penyediaan jasa akomodasi penginapan bagi tim pelaksana guna mendukung kelancaran kegiatan pemantauan serta evaluasi penyelenggaraan SPIP Terintegrasi, khususnya dalam rangka koordinasi teknis dan pendampingan tim BPKP di lokasi tujuan. Spesifikasi pekerjaan mencakup penyediaan kamar dengan fasilitas yang memadai untuk istirahat serta ruang koordinasi tim, disesuaikan dengan ketentuan kelas jabatan dan golongan masing-masing personil sesuai aturan perjalanan dinas yang berlaku. Lokasi penginapan diprioritaskan pada area yang memiliki aksesibilitas optimal serta kedekatan dengan kantor UPT yang menjadi lokus evaluasi tim BPKP guna memastikan sinkronisasi data dan efektivitas waktu dalam proses verifikasi di lapangan. Besaran biaya penginapan wajib mematuhi batasan tertinggi Standar Biaya Masukan (SBM) tahun anggaran berjalan untuk wilayah terkait, dengan mekanisme pertanggungjawaban berdasarkan biaya riil (at cost) yang dibuktikan melalui kuitansi atau faktur resmi hotel sebagai dokumen validasi keuangan negara yang sah.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2804532);
