INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66537422', 66537422, 'analyze_legacy', 'Badan Pusat Statistik', 'central', 'BADAN PUSAT STATISTIK KAB KULON PROGO', 'Biaya Jasa Manajemen Building', 'Jasa Lainnya', 'E-Purchasing', 'DI Yogyakarta, Kulon Progo (Kab.)', 84750000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1, Paket, @ 128859000 )', '1. Biaya Jasa Manajemen Building ( 1, Paket, @ 128859000 );', 'Pengadaan SAtpam1. Kelengkapan administrasi/Legalitas: 1) Memiliki izin Usaha : 2) Memiliki Tanda Daftar Perusahaan (TDP) atau NIB; 3) Memiliki Akta Pendirian Perusahaan dan Akta Perubahan Terakhir (apabila ada); 4) Memiliki NPWP (Nomor Pokok Wajib Pajak) dan telah memenuhi kewajiban perpajakan tahun pajak terakhir (SPT tahunan) Tahun 2025; 5) Mempunyai atau menguasai tempat usaha/kantor dengan alamat yang benar, tetap dan jelas berupa milik sendiri atau sewa; 6) Secara hukum mempunyai kapasitas untuk mengikatkan diri pada kontrak yang dibuktikan dengan: a. Akta Pendirian Perusahaan beserta perubahannya (apabila ada perubahan); b. Surat Kuasa (apabila dikuasakan); c. Bukti bahwa yang diberikan kuasa merupakan pegawai tetap (apabila dikuasakan); d. Kartu Tanda Penduduk (KTP). 7) Dalam hal Peserta melakukan Kemitraan harus mempunyai perjanjian Kemitraan 2. Memiliki SDM yang memenuhi syarat umum dan kualifikasi teknis sebagai berikut: 1.1. Syarat Umum: - Pria / Wanita Usia 20-55 Tahun - Jujur dan berdedikasi tinggi - Sehat jasmani dan rohani. - Pendidikan minimal SLTA/Sederajat - Memiliki pengalaman kerja di posisi yang sama minimal 2 (dua) tahun - Tidak memiliki Tatoo/bekas Tatoo pada bagian tubuh yang terlihat dan tidak bertindik 1.2. Kualifikasi Teknis: a. Anggota Keamanan, sebanyak 2 orang: • Mempunyai minimal sertifikat keahlian Gada Pratama dari kepolisian atau pihak yang bekerja sama dengan kepolisian • wajib memiliki Kartu Tanda Anggota dari Kepolisian atau Pihak yang bekerjasama dengan Kepolisian, yang masih berlaku. • Mempunyai kemampuan komunikasi yang baik untuk melaksanakan tugas sebagai front office atau receiptionis.', 44010900, 'low', NULL, NULL, NULL, 1, 0, 1, 0, 1, 2805041);
