INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66535477', 66535477, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'INSPEKTORAT UTAMA BADAN POM', 'Transport pada Sosialisasi Program Anti Korupsi', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 60000000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '( 10, OK, @ 6000000 )', '1. Transport ( 10, OK, @ 6000000 );', 'Penyediaan jasa transportasi bagi tim sosialisasi guna mendukung mobilisasi dari tempat kedudukan menuju lokasi Unit Pelaksana Teknis (UPT) tujuan dalam rangka pelaksanaan program anti korupsi. Spesifikasi ini mencakup penggunaan moda transportasi darat yang memadai yang dipilih berdasarkan prinsip efektivitas waktu, efisiensi anggaran, serta kemudahan akses menuju lokasi UPT yang bersangkutan. Ruang lingkup pekerjaan juga meliputi biaya transportasi lokal di wilayah UPT serta biaya transportasi dari kediaman/kantor menuju titik keberangkatan (stasiun/bandara/terminal) sesuai dengan rute penugasan yang ditetapkan dalam Surat Tugas. Pemilihan moda transportasi dilakukan dengan mempertimbangkan kondisi geografis lokasi UPT guna memastikan kelancaran jadwal sosialisasi dan jangkauan edukasi kepada seluruh pegawai. Besaran biaya yang dikeluarkan wajib merujuk pada ketentuan tarif yang berlaku atau batas tertinggi Standar Biaya Masukan (SBM) tahun anggaran berjalan, dengan mekanisme pertanggungjawaban berdasarkan biaya riil (at cost) yang didukung oleh bukti pembayaran atau dokumen elektronik yang sah sesuai kaidah akuntabilitas keuangan negara.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2806030);
