INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66534717', 66534717, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'INSPEKTORAT UTAMA BADAN POM', 'Penginapan pada Pemantauan dan Evaluasi TL Hasil Pengawasan', 'Jasa Lainnya', 'Dikecualikan', 'DKI Jakarta, Jakarta Pusat (Kota)', 1800000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '( 2, OH, @ 900000 )', '1. Penginapan ( 2, OH, @ 900000 );', 'Penyediaan jasa akomodasi penginapan bagi tim pelaksana guna mendukung kelancaran kegiatan pemantauan dan evaluasi tindak lanjut hasil pengawasan di lokasi tujuan. Spesifikasi pekerjaan mencakup penyediaan kamar dengan fasilitas yang memadai untuk aktivitas istirahat serta koordinasi tim, dengan kapasitas hunian yang disesuaikan berdasarkan ketentuan kelas jabatan dan golongan masing-masing personil sesuai aturan perjalanan dinas yang berlaku. Lokasi penginapan diprioritaskan pada area yang memiliki aksesibilitas optimal menuju instansi atau objek pemantauan guna memastikan efektivitas waktu pelaksanaan evaluasi di lapangan. Besaran biaya penginapan mengacu pada batasan plafon Standar Biaya Masukan (SBM) tahun anggaran berjalan untuk wilayah terkait, dengan mekanisme pertanggungjawaban berdasarkan biaya riil (at cost) yang didukung oleh bukti reservasi dan kuitansi resmi sebagai dokumen validasi keuangan negara.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2806294);
