INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66535470', 66535470, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'INSPEKTORAT UTAMA BADAN POM', 'Makan Rapat pada Pembangunan Zona Integritas Inspektorat I', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 1539000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 27, OK, @ 57000 )', '1. Makan Rapat Biasa D.K.I. JAKARTA ( 27, OK, @ 57000 );', 'Penyediaan jasa boga berupa makan siang guna mendukung kelancaran pelaksanaan kegiatan terkait pembangunan Zona Integritas di unit kerja Inspektorat I. Spesifikasi hidangan mencakup penyajian menu yang layak konsumsi sesuai standar layanan rapat formal. Kegiatan Pembangunan ZI melibatkan koordinasi strategis di lingkup Kantor Pusat yang memerlukan durasi pembahasan teknis secara mendalam. Penyajian makan siang dapat dilakukan secara prasmanan (buffet) atau kotak (box) dengan mempertimbangkan efektivitas waktu serta fleksibilitas ruang koordinasi di lokasi kegiatan. Penentuan harga satuan paket makan siang wajib sepenuhnya patuh pada batas tertinggi Standar Biaya Masukan (SBM) tahun anggaran berjalan yang berlaku untuk kategori konsumsi rapat, dengan memperhatikan durasi rapat koordinasi yang dilaksanakan sekurang-kurangnya 2 (dua) jam. Seluruh pengadaan ini mengutamakan prinsip efisiensi anggaran negara, di mana mekanisme pembayaran dilakukan berdasarkan realisasi jumlah kehadiran fisik peserta rapat yang dibuktikan dengan daftar hadir resmi, kuitansi/faktur penagihan yang sah, serta pemenuhan kewajiban administrasi perpajakan yang sesuai dengan ketentuan perundang-undangan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2806886);
