INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66535471', 66535471, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'INSPEKTORAT UTAMA BADAN POM', 'Snack Rapat Biasa pada Pendampingan Pemeriksaan', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 8035000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 372, OK, @ 21600 )', '1. Snack Rapat Biasa D.K.I. JAKARTA ( 372, OK, @ 21600 );', 'Penyediaan jasa boga berupa kudapan (snack) guna mendukung kelancaran kegiatan pendampingan pemeriksaan yang melibatkan partisipasi aktif dari berbagai unit kerja lintas Eselon I. Spesifikasi hidangan mencakup penyajian variasi penganan yang layak konsumsi, sehat, dan higienis, yang disajikan bersama dengan air mineral atau pilihan minuman sesuai standar layanan rapat. Mengingat sifat kegiatan yang memerlukan koordinasi intensif dan diskusi teknis antar unit kerja dalam durasi tertentu, penyajian kudapan dilakukan dengan mempertimbangkan efektivitas waktu serta fleksibilitas ruang koordinasi di lokasi kegiatan. Penentuan harga satuan paket kudapan wajib sepenuhnya patuh pada batas tertinggi Standar Biaya Masukan (SBM) tahun anggaran berjalan yang berlaku untuk kategori snack rapat di lokasi terkait. Seluruh pengadaan ini mengutamakan prinsip efisiensi anggaran negara, di mana mekanisme pembayaran dilakukan berdasarkan realisasi jumlah kehadiran fisik peserta rapat yang dibuktikan dengan daftar hadir resmi, kuitansi, serta pemenuhan kewajiban administrasi perpajakan yang sah sesuai ketentuan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2807294);
