INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66535468', 66535468, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'INSPEKTORAT UTAMA BADAN POM', 'Makan Rapat pada Pemantauan SPIP', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 6156000, 'June 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 108, OK, @ 57000 )', '1. Makan Rapat DKI Jakarta ( 108, OK, @ 57000 );', 'Penyediaan makan siang guna mendukung kelancaran pelaksanaan kegiatan terkait evaluasi SPIP Terintegrasi. Spesifikasi hidangan mencakup penyajian menu yang berkualitas dan layak santap. Penyajian makan siang dapat dilakukan secara prasmanan (buffet) atau kotak (box) dengan mempertimbangkan efektivitas waktu serta ketersediaan ruang koordinasi di lokasi kegiatan. Penentuan harga satuan paket makan wajib sepenuhnya patuh pada batas tertinggi Standar Biaya Masukan (SBM) tahun anggaran berjalan yang berlaku untuk kategori konsumsi rapat di lokasi terkait, dengan memperhatikan durasi rapat koordinasi yang dilaksanakan sekurang-kurangnya 2 (dua) jam. Seluruh pengadaan ini mengutamakan prinsip efisiensi anggaran negara, di mana mekanisme pembayaran dilakukan berdasarkan realisasi jumlah kehadiran fisik peserta rapat yang dibuktikan dengan daftar hadir resmi, kuitansi, serta pemenuhan kewajiban administrasi perpajakan yang sah.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2807921);
