INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66501863', 66501863, 'analyze_legacy', 'Kota Magelang', 'kabkota', 'Dinas Penanaman Modal dan Pelayanan Terpadu Satu Pintu', 'Belanja Perjalanan Dinas Biasa-Umum', 'Barang', 'Dikecualikan', 'Jawa Tengah, Magelang (Kota)', 38404000, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Satuan biaya tiket pesawat perjalanan dinas dalam negeri pergi pulang (pp), uang harian perjalanan dinas dalam negeri untuk ASN/Pejabat Negara/pejabat daerah, satuan biaya penginapan perjalanan dinas dalam negeri, uang representasi perjalanan dinas dalam rangka Kunjungan Kerja dan Perjalanan Dinas ke DKI Jakarta. Uang harian perjalanan dinas dalam negeri untuk ASN/Pejabat Negara/pejabat daerah, ,uang representasi perjalanan dinas, uang harian Non ASN, biaya transport menggunakan kendaraan roda 4 dalam rangka perjalanan dinas Jawa Tengah tidak menginap. Uang harian perjalanan dinas dalam negeri untuk ASN/Pejabat Negara/pejabat daerah, tarif biaya penginapan, uang representasi, uang harian non ASN, perjalanan dinas dalam rangka biaya transport menggunakan kendaraan roda 4 dalam rangka perjalanan dinas Jawa Tengah menginap.', 'Satuan biaya tiket pesawat perjalanan dinas dalam negeri pergi pulang (pp) kota asal Jakarta tujuan Yogyakarta. Kelas Ekonomi, uang harian perjalanan dinas dalam negeri untuk ASN/Pejabat Negara/pejabat daerah dengan tujuan ke Prop DKI Jakarta, satuan biaya penginapan perjalanan dinas dalam negeri di prop DKI Jakarta dan penginapan untuk anggota DPRD, Pejabat Pimpinan Tinggi, uang representasi perjalanan dinas pejabat ess 2 dalam rangka Kunjungan Kerja dan Perjalanan Dinas ke DKI Jakarta. Uang harian perjalanan dinas dalam negeri untuk ASN/Pejabat Negara/pejabat daerah tujuan ke Prop Jawa Tengah, ,uang representasi perjalanan dinas untuk ess 2, uang harian Non ASN tujuan prop Jawa Tengah, biaya transport menggunakan kendaraan roda 4 perjalanan dinas ke kota Semarang (80 km x 2) dalam rangka perjalanan dinas Jawa Tengah tidak menginap. Uang harian perjalanan dinas dalam negeri untuk ASN/Pejabat Negara/pejabat daerah ke Prop Jawa Tengah, tarif biaya penginapan unt pejabat administrator/Fungsional, uang representasi unt pejabat ess 2, uang harian non ASN dgn tujuan ke prop Jawa Tengah, biaya transport menggunakan kendaraan roda 4 ke Kota Semarang (80 km x 2) dalam rangka perjalanan dinas Jawa Tengah menginap.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2808316);
