INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66535469', 66535469, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'INSPEKTORAT UTAMA BADAN POM', 'Snack Rapat Biasa pada Pembangunan Zona Integritas Inspektorat I', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 2593000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 120, OK, @ 21609 )', '1. Snack Rapat Biasa D.K.I. JAKARTA ( 120, OK, @ 21609 );', 'Penyediaan kudapan (snack) guna mendukung kelancaran pelaksanaan kegiatan terkait pembangunan Zona Integritas di unit kerja Inspektorat I. Spesifikasi hidangan mencakup penyajian variasi penganan yang layak konsumsi sesuai standar layanan rapat. Kegiatan Pembangunan ZI melibatkan koordinasi strategis di lingkup Kantor Pusat. Namun demikian, penyajian kudapan dilakukan dengan mempertimbangkan efektivitas waktu serta fleksibilitas ruang koordinasi di lokasi kegiatan. Penentuan harga satuan paket kudapan wajib sepenuhnya patuh pada batas tertinggi Standar Biaya Masukan (SBM) tahun anggaran berjalan yang berlaku untuk kategori snack rapat, dengan memperhatikan durasi rapat koordinasi yang dilaksanakan sekurang-kurangnya 2 (dua) jam. Seluruh pengadaan ini mengutamakan prinsip efisiensi anggaran negara, di mana mekanisme pembayaran dilakukan berdasarkan realisasi jumlah kehadiran fisik peserta rapat yang dibuktikan dengan daftar hadir resmi, kuitansi/faktur penagihan yang sah, serta pemenuhan kewajiban administrasi perpajakan yang sesuai dengan ketentuan perundang-undangan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2809513);
